module tb;
    reg clk;
    reg reset;
    wire [31:0] q;

    integer errors = 0;
    integer i;
    reg [31:0] expected_q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Task to compute expected next state for a 32-bit Galois LFSR
    // with taps at positions 32, 22, 2, 1 (1-indexed), which correspond
    // to bit positions 31, 21, 1, 0 (0-indexed).
    // In a standard Galois LFSR configuration:
    // If output bit (current q[0]) is 1, then positions corresponding to taps
    // are XORed with 1. Here taps are at 31, 21, 1, 0.
    function [31:0] next_lfsr(input [31:0] current);
        reg feedback;
        begin
            feedback = current[0];
            // Shift right by 1, and XOR tap positions if feedback is 1
            next_lfsr = {1'b0, current[31:1]};
            if (feedback) begin
                next_lfsr[31]   = next_lfsr[31]   ^ 1'b1; // Tap 32 (bit 31)
                next_lfsr[21]   = next_lfsr[21]   ^ 1'b1; // Tap 22 (bit 21)
                next_lfsr[1]    = next_lfsr[1]    ^ 1'b1; // Tap 2  (bit 1)
                next_lfsr[0]    = next_lfsr[0]    ^ 1'b1; // Tap 1  (bit 0)
            end
        end
    endfunction

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        expected_q = 32'h1;

        // Apply reset
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== 32'h1) begin
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        #1;
        reset = 0;

        // Check reset value synchronously
        if (q !== 32'h1) begin
            errors = errors + 1;
        end

        // Run through multiple clock cycles and check against golden model
        for (i = 0; i < 20; i = i + 1) begin
            expected_q = next_lfsr(expected_q);
            @(posedge clk);
            #1; // small delay to sample after clock edge
            if (q !== expected_q) begin
                errors = errors + 1;
            end
        end

        // Test asynchronous/synchronous reset interruption mid-stream
        @(posedge clk);
        reset = 1;
        expected_q = 32'h1;
        #1;
        if (q !== 32'h1) begin
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;
        #1;
        if (q !== 32'h1) begin
            errors = errors + 1;
        end

        // Check a few more cycles after second reset release
        for (i = 0; i < 5; i = i + 1) begin
            expected_q = next_lfsr(expected_q);
            @(posedge clk);
            #1;
            if (q !== expected_q) begin
                errors = errors + 1;
            end
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
